/*
    All distinct 2025 records in the Ministry of Transport two-wheel registry
    (one row per normalized make/model/year/engine-cc combination).
    Source: https://data.gov.il/dataset/0f16b39a-6016-408d-805d-31f40d5a0990
    Resource: bf9df4e2-d90d-4c0a-a400-19e15af8e95f

    The registry provides source make, model code, model year and engine cc.
    Manufacturer names are normalized to familiar brand names where possible;
    Model is the source registry code/name, not necessarily a retail model name.
    Price, motorcycle type, rider experience, usage and maintenance cost are
    heuristic estimates, marked below. Reliability is explicitly Not rated.
    ImageUrl has no reliable licensed source and remains NULL.

    Price heuristic (ILS): 0cc=30,000; up to 50=8,000; up to 125=16,000;
    up to 250=26,000; up to 400=38,000; up to 500=49,000; up to 700=65,000;
    up to 900=90,000; up to 1100=135,000; above 1100=180,000.
    These are broad placeholders, not market prices. Verify before relying on them.

    Run 001_CreateMotorcycles.sql first. This script is safe to rerun.
*/

IF DB_ID(N'MotorcycleAI') IS NULL
BEGIN
    THROW 50002, 'Run 001_CreateMotorcycles.sql first to create the MotorcycleAI database.', 1;
END;
GO

USE [MotorcycleAI];
GO

IF OBJECT_ID(N'dbo.Motorcycles', N'U') IS NULL
BEGIN
    THROW 50001, 'Run 001_CreateMotorcycles.sql first to create dbo.Motorcycles.', 1;
END;
GO

IF COL_LENGTH(N'dbo.Motorcycles', N'PriceIsEstimate') IS NULL
BEGIN
    ALTER TABLE dbo.Motorcycles ADD PriceIsEstimate BIT NOT NULL CONSTRAINT DF_Motorcycles_PriceIsEstimate DEFAULT (0);
END;
GO

IF COL_LENGTH(N'dbo.Motorcycles', N'AttributesAreEstimated') IS NULL
BEGIN
    ALTER TABLE dbo.Motorcycles ADD AttributesAreEstimated BIT NOT NULL CONSTRAINT DF_Motorcycles_AttributesAreEstimated DEFAULT (0);
END;
GO

UPDATE dbo.Motorcycles
SET PriceIsEstimate = 1,
    AttributesAreEstimated = 1
WHERE Description LIKE N'%Illustrative sample data%';
GO

UPDATE dbo.Motorcycles
SET VehicleType = COALESCE(VehicleType, N'Motorcycle'),
    RiderExperience = COALESCE(RiderExperience, CASE WHEN EngineCC <= 250 THEN N'Beginner' WHEN EngineCC <= 700 THEN N'Intermediate' ELSE N'Advanced' END),
    [Usage] = COALESCE([Usage], CASE WHEN MotorcycleType = N'Scooter' THEN N'Commuting' WHEN MotorcycleType = N'Sport' THEN N'Sport riding' WHEN MotorcycleType = N'Off-road' THEN N'Off-road' WHEN MotorcycleType IN (N'Adventure', N'Scrambler') THEN N'Touring and mixed terrain' ELSE N'General riding' END),
    Reliability = COALESCE(Reliability, N'Not rated'),
    MaintenanceCost = COALESCE(MaintenanceCost, CASE WHEN EngineCC <= 125 THEN N'Low' WHEN EngineCC <= 500 THEN N'Medium' ELSE N'High' END),
    AttributesAreEstimated = 1
WHERE VehicleType IS NULL OR RiderExperience IS NULL OR [Usage] IS NULL OR Reliability IS NULL OR MaintenanceCost IS NULL;
GO

INSERT INTO dbo.Motorcycles
    (Manufacturer, Model, [Year], EngineCC, Price, PriceIsEstimate, AttributesAreEstimated, VehicleType, MotorcycleType, RiderExperience, [Usage], Reliability, MaintenanceCost, Description)
