    source.Manufacturer,
    source.Model,
    source.[Year],
    source.EngineCC,
    source.Price,
    1,
    1,
    N'Motorcycle',
    source.MotorcycleType,
    source.RiderExperience,
    source.[Usage],
    source.Reliability,
    source.MaintenanceCost,
    source.Description
