WHERE NOT EXISTS
(
    SELECT 1
    FROM dbo.Motorcycles AS existing
    WHERE existing.Manufacturer = source.Manufacturer
      AND existing.Model = source.Model
      AND existing.[Year] = source.[Year]
);
GO

SELECT COUNT(*) AS TotalMotorcycles,
       SUM(CASE WHEN PriceIsEstimate = 1 THEN 1 ELSE 0 END) AS RowsWithEstimatedPrice,
       SUM(CASE WHEN AttributesAreEstimated = 1 THEN 1 ELSE 0 END) AS RowsWithEstimatedAttributes
FROM dbo.Motorcycles;
GO
